"""Data loading for the ADBench cardio dataset (R10: labels never touch scoring).

Priority chain:
  1. REPRO_DATA_CACHE/6_cardio.npz        (shared cache across runs)
  2. <workspace>/data/cardio.npz          (local cache written by a previous run)
  3. Download from the ADBench GitHub repository (raw), then cache into
     REPRO_DATA_CACHE (if set) and <workspace>/data/.

Validation gate (paper Table 3 signature): 1831 samples, 21 features,
176 anomalies (9.61%), no NaN/inf. Any source failing the gate is rejected.
"""

import io
import json
import os
import urllib.request

import numpy as np

AD BENCH_RAW = None  # placeholder to avoid accidental typos below
ADBENCH_RAW_URL = (
    "https://raw.githubusercontent.com/Minqi824/ADBench/main/"
    "adbench/datasets/Classical/6_cardio.npz"
)
ADBENCH_API_TREE = (
    "https://api.github.com/repos/Minqi824/ADBench/git/trees/main?recursive=1"
)

EXPECTED = {
    "n_samples": 1831,
    "n_features": 21,
    "n_anomalies": 176,
    "anomaly_rate": 176 / 1831,  # 0.0961
}


def _cache_dir():
    return os.environ.get("REPRO_DATA_CACHE")


def _workspace_cache():
    return os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "data")


def _validate(X, y, source, log):
    """Hard validation gate against the paper's Table 3 signature."""
    problems = []
    if X.shape != (EXPECTED["n_samples"], EXPECTED["n_features"]):
        problems.append(f"shape {X.shape} != (1831, 21)")
    if int(y.sum()) != EXPECTED["n_anomalies"]:
        problems.append(f"anomalies {int(y.sum())} != 176")
    if not np.isfinite(X).all():
        problems.append("NaN/inf present in X")
    if not set(np.unique(y).tolist()) <= {0, 1}:
        problems.append("labels are not binary 0/1")
    entry = {
        "source": source,
        "shape": list(X.shape),
        "n_anomalies": int(y.sum()),
        "anomaly_rate": float(y.mean()),
        "ok": not problems,
        "problems": problems,
    }
    log.append(entry)
    return not problems


def _load_npz_bytes(raw):
    d = np.load(io.BytesIO(raw), allow_pickle=True)
    keys = set(d.keys())
    if {"X", "y"} <= keys:
        return d["X"].astype(np.float64), d["y"].astype(np.int64).ravel()
    raise ValueError(f"npz does not contain X/y keys: {sorted(keys)}")


def _try_download(url, timeout=120):
    req = urllib.request.Request(url, headers={"User-Agent": "svead-repro"})
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return resp.read()


def load_cardio():
    """Return (X, y, provenance) for the ADBench cardio dataset.

    X : float64 array (1831, 21), already per-column standardized in the
        official ADBench artifact (col mean ~0, col std ~0.9997).
    y : int64 array (1831,), 1 = anomaly (176 ones), 0 = normal.
    Labels are returned separately and are never used by the scoring code
    (unsupervised protocol, R10).
    """
    validation_log = []

    # 1) shared cache
    candidates = []
    cd = _cache_dir()
    if cd:
        candidates += [
            os.path.join(cd, "6_cardio.npz"),
            os.path.join(cd, "cardio_adbench.npz"),
        ]
    # 2) workspace cache
    candidates.append(os.path.join(_workspace_cache(), "cardio.npz"))

    for path in candidates:
        if os.path.exists(path):
            try:
                d = np.load(path, allow_pickle=True)
                X = d["X"].astype(np.float64)
                y = d["y"].astype(np.int64).ravel()
                if _validate(X, y, f"cache:{path}", validation_log):
                    return X, y, {
                        "resolved_from": f"cache:{path}",
                        "validation_log": validation_log,
                    }
            except Exception as exc:  # corrupt file -> keep looking
                validation_log.append({"source": f"cache:{path}", "ok": False,
                                       "problems": [f"load error: {exc}"]})

    # 3) download from ADBench GitHub (discover path via the git tree first,
    #    fall back to the known layout path).
    urls = [ADBENCH_RAW_URL]
    try:
        tree = json.loads(_try_download(ADBENCH_API_TREE, timeout=60).decode())
        hits = [
            it["path"] for it in tree.get("tree", [])
            if "cardio" in it.get("path", "").lower()
            and it["path"].lower().endswith(".npz")
        ]
        urls = [
            f"https://raw.githubusercontent.com/Minqi824/ADBench/main/{p}"
            for p in hits
        ] + urls
    except Exception as exc:
        validation_log.append({"source": "github-tree", "ok": False,
                               "problems": [f"tree lookup failed: {exc}"]})

    last_err = None
    for url in urls:
        try:
            raw = _try_download(url)
            X, y = _load_npz_bytes(raw)
            if _validate(X, y, f"download:{url}", validation_log):
                # cache for future runs
