"""Evaluation helpers (R9, R10).

All functions take scores first and labels second: labels are consumed
only after anomaly scores have been produced, preserving the unsupervised
evaluation protocol.
"""

import numpy as np
from sklearn.metrics import (
    average_precision_score,
    precision_recall_curve,
    roc_auc_score,
)


def roc_auc(scores, labels):
    """AUC-ROC (R9)."""
    return float(roc_auc_score(labels, scores))


def auc_pr_average_precision(scores, labels):
    """AUC-PR as average precision (ADBench convention, R9) - primary."""
    return float(average_precision_score(labels, scores))


def auc_pr_trapezoid(scores, labels):
    """Trapezoidal AUC of the precision-recall curve - secondary variant."""
    precision, recall, _ = precision_recall_curve(labels, scores)
    order = np.argsort(recall)
    return float(np.trapezoid(precision[order], recall[order]))


def summarize(values):
    """Mean/std/min/max over repeated runs (R8)."""
    v = np.asarray(list(values), dtype=np.float64)
    return {
        "mean": float(v.mean()),
        "std_ddof0": float(v.std(ddof=0)),
        "std_ddof1": float(v.std(ddof=1)) if v.size > 1 else 0.0,
        "min": float(v.min()),
        "max": float(v.max()),
        "n": int(v.size),
        "values": [float(x) for x in v],
    }

